from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    if n == 0:
        return 1
    k = len(alphabet)
    if not banned:
        return pow(k, n, MOD)

    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}
    children: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = children[node][c]
            if nxt == -1:
                nxt = len(children)
                children[node][c] = nxt
                children.append([-1] * k)
                bad.append(False)
            node = nxt
        bad[node] = True

    num_nodes = len(children)
    fail = [0] * num_nodes
    trans = [[0] * k for _ in range(num_nodes)]
    q: deque[int] = deque()

    for c in range(k):
        v = children[0][c]
        if v != -1:
            trans[0][c] = v
            fail[v] = 0
            q.append(v)
        else:
            trans[0][c] = 0

    while q:
        u = q.popleft()
        f = fail[u]
        if bad[f]:
            bad[u] = True
        for c in range(k):
            v = children[u][c]
            if v != -1:
                trans[u][c] = v
                fail[v] = trans[f][c]
                if bad[u]:
                    bad[v] = True
                q.append(v)
            else:
                trans[u][c] = trans[f][c]

    good_id = [-1] * num_nodes
    m = 0
    for u in range(num_nodes):
        if not bad[u]:
            good_id[u] = m
            m += 1

    mat = [[0] * m for _ in range(m)]
    for u in range(num_nodes):
        ui = good_id[u]
        if ui == -1:
            continue
        for c in range(k):
            vi = good_id[trans[u][c]]
            if vi != -1:
                mat[ui][vi] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        b_t = list(zip(*b))
        return [
            [sum(x * y for x, y in zip(row, col)) % MOD for col in b_t]
            for row in a
        ]

    vec = [0] * m
    vec[0] = 1
    exp = n
    base = mat
    while exp > 0:
        if exp & 1:
            base_t = list(zip(*base))
            vec = [sum(x * y for x, y in zip(vec, col)) % MOD for col in base_t]
        exp >>= 1
        if exp:
            base = mat_mul(base, base)

    return sum(vec) % MOD
